"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["90857"],{48881(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_indevida","status":422,"titulo":"A resolu\xe7\xe3o de Pesos por \xc1rea s\xf3 se aplica \xe0 classifica\xe7\xe3o baseada em ENEM com c\xe1lculo local"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_indevida","requisitos":[],"oQueAconteceu":["A classifica\xe7\xe3o informou `resolucaoPesoAreaEnem` (ou, na configura\xe7\xe3o congelada, traz um\\nquadro de pesos por \xe1rea), mas n\xe3o \xe9 uma classifica\xe7\xe3o baseada em ENEM com c\xe1lculo local pela\\nm\xe9dia ponderada. Isso acontece quando a classifica\xe7\xe3o n\xe3o est\xe1 marcada como baseada em ENEM\\n(`baseadoEmEnem: false`) ou quando a regra de c\xe1lculo n\xe3o \xe9 `FORMULA_MEDIA_PONDERADA`, como na\\nclassifica\xe7\xe3o importada (`CLASSIFICACAO_IMPORTADA`). S\xf3 a m\xe9dia ponderada baseada em ENEM usa\\no quadro de pesos por \xe1rea.","A recusa vem no campo `resolucaoPesoAreaEnem` e acumula, na mesma resposta, com as demais\\nviola\xe7\xf5es da classifica\xe7\xe3o. Nessas combina\xe7\xf5es o cadastro de Pesos por \xc1rea n\xe3o \xe9 consultado.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na defini\xe7\xe3o da classifica\xe7\xe3o, conforme a causa:","- **O processo n\xe3o calcula a nota pelos pesos por \xe1rea do ENEM:** remova\\n  `resolucaoPesoAreaEnem`.\\n- **O processo deveria calcular pelos pesos por \xe1rea do ENEM:** corrija a classifica\xe7\xe3o para\\n  `baseadoEmEnem: true` com a regra de c\xe1lculo `FORMULA_MEDIA_PONDERADA`, e mantenha a\\n  resolu\xe7\xe3o; ver tamb\xe9m\\n  [`resolucao_peso_area_enem_obrigatoria`](/erros/uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_obrigatoria).","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);